src/types.ts:
export interface Team {
  id: string;
  name: string;
  shortName: string;
  color?: string; // Hex or tailwind color class
  groupId?: 'A' | 'B' | 'C';
}

export type GroupId = 'A' | 'B' | 'C';

export interface Group {
  id: GroupId;
  name: string;
  teamIds: string[];
}

export interface Match {
  id: string;
  groupId?: GroupId; // undefined for knockout matches
  stage: 'group' | 'semi-final' | 'final' | 'third-place';
  homeTeamId: string;
  awayTeamId: string;
  homeScore: number | null;
  awayScore: number | null;
  homePenalty?: number | null; // For knockout draws
  awayPenalty?: number | null;
  round: number; // 1 to 6 for double round robin
  isPlayed: boolean;
  dateStr?: string;
  matchNumber?: number;
}

export interface TeamStats {
  teamId: string;
  teamName: string;
  shortName: string;
  color?: string;
  groupId: GroupId;
  played: number;
  won: number;
  drawn: number;
  lost: number;
  goalsFor: number;
  goalsAgainst: number;
  goalDifference: number;
  points: number;
  rank: number;
  isQualified: boolean;
  qualificationReason?: string; // e.g., 'Grup Lideri' or 'En İyi 2.'
}

export interface KnockoutMatchData {
  id: string;
  title: string;
  stage: 'semi-final' | 'final' | 'third-place';
  homeTeamId: string | null;
  awayTeamId: string | null;
  homeScore: number | null;
  awayScore: number | null;
  homePenalty?: number | null;
  awayPenalty?: number | null;
  winnerId: string | null;
  isPlayed: boolean;
  slotHomeDescription?: string; // e.g. "A Grubu 1.si"
  slotAwayDescription?: string; // e.g. "En İyi 2. Takım"
}

export interface SaveSlot {
  id: string;
  name: string;
  savedAt: string;
  playedCount: number;
  totalCount: number;
  data: {
    teams: Team[];
    groups: Group[];
    matches: Match[];
    knockoutMatches: KnockoutMatchData[];
  };
}

export interface TournamentState {
  teams: Team[];
  groups: Group[];
  matches: Match[];
  knockoutMatches: KnockoutMatchData[];
  stage: 'setup' | 'group' | 'knockout' | 'finished';
  winnerTeamId?: string;
}

src/App.tsx:
import React, { useState, useEffect, useMemo } from 'react';
import {
  createInitialTeams,
  createInitialKnockoutMatches,
  generateGroupMatches,
  shuffleTeamsIntoGroups,
  calculateGroupStandings,
  calculateBestSeconds,
  updateKnockoutSlots,
  generateSampleTournamentData,
} from './utils/tournament';
import { Group, GroupId, KnockoutMatchData, Match, SaveSlot, Team, TeamStats } from './types';
import { Header } from './components/Header';
import { TeamSetup } from './components/TeamSetup';
import { GroupStandings } from './components/GroupStandings';
import { BestSecondTable } from './components/BestSecondTable';
import { MatchList } from './components/MatchList';
import { KnockoutBracket } from './components/KnockoutBracket';
import { StatsOverview } from './components/StatsOverview';
import { WinnerModal } from './components/WinnerModal';
import { SaveManagerModal } from './components/SaveManagerModal';

const LOCAL_STORAGE_KEY = 'turnuva_puan_tablosu_v1';
const SAVE_SLOTS_KEY = 'turnuva_save_slots_v1';

export default function App() {
  const [activeTab, setActiveTab] = useState<'setup' | 'group' | 'bestSeconds' | 'knockout'>('group');
  const [isSaveManagerOpen, setIsSaveManagerOpen] = useState<boolean>(false);
  const [lastSavedAt, setLastSavedAt] = useState<Date | null>(new Date());

  // Save Slots State
  const [saveSlots, setSaveSlots] = useState<SaveSlot[]>(() => {
    const saved = localStorage.getItem(SAVE_SLOTS_KEY);
    if (saved) {
      try {
        return JSON.parse(saved);
      } catch (e) {}
    }
    return [];
  });

  // Initialize Tournament State
  const [teams, setTeams] = useState<Team[]>(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.teams) return parsed.teams;
      } catch (e) {
        console.error('Failed to load storage', e);
      }
    }
    const initial = createInitialTeams();
    const { teams: grouped } = shuffleTeamsIntoGroups(initial);
    return grouped;
  });

  const [groups, setGroups] = useState<Group[]>(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.groups) return parsed.groups;
      } catch (e) {}
    }
    return [
      { id: 'A', name: 'A Grubu', teamIds: teams.filter((t) => t.groupId === 'A').map((t) => t.id) },
      { id: 'B', name: 'B Grubu', teamIds: teams.filter((t) => t.groupId === 'B').map((t) => t.id) },
      { id: 'C', name: 'C Grubu', teamIds: teams.filter((t) => t.groupId === 'C').map((t) => t.id) },
    ];
  });

  const [matches, setMatches] = useState<Match[]>(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.matches) return parsed.matches;
      } catch (e) {}
    }
    return generateGroupMatches([
      { id: 'A', name: 'A Grubu', teamIds: teams.filter((t) => t.groupId === 'A').map((t) => t.id) },
      { id: 'B', name: 'B Grubu', teamIds: teams.filter((t) => t.groupId === 'B').map((t) => t.id) },
      { id: 'C', name: 'C Grubu', teamIds: teams.filter((t) => t.groupId === 'C').map((t) => t.id) },
    ]);
  });

  const [knockoutMatches, setKnockoutMatches] = useState<KnockoutMatchData[]>(() => {
    const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        if (parsed.knockoutMatches) return parsed.knockoutMatches;
      } catch (e) {}
    }
    return createInitialKnockoutMatches();
  });

  const [showWinnerModal, setShowWinnerModal] = useState<boolean>(false);

  // Save state to LocalStorage
  useEffect(() => {
    const payload = { teams, groups, matches, knockoutMatches };
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(payload));
    setLastSavedAt(new Date());
  }, [teams, groups, matches, knockoutMatches]);

  // Persist Save Slots
  useEffect(() => {
    localStorage.setItem(SAVE_SLOTS_KEY, JSON.stringify(saveSlots));
  }, [saveSlots]);

  // Handle Save Slot Creation
  const handleSaveSlot = (name: string) => {
    const playedCount = matches.filter((m) => m.isPlayed).length;
    const newSlot: SaveSlot = {
      id: Date.now().toString(),
      name,
      savedAt: new Date().toLocaleDateString('tr-TR', {
        day: 'numeric',
        month: 'long',
        hour: '2-digit',
        minute: '2-digit',
      }),
      playedCount,
      totalCount: matches.length,
      data: { teams, groups, matches, knockoutMatches },
    };
    setSaveSlots((prev) => [newSlot, ...prev]);
  };

  // Handle Loading Data
  const handleLoadData = (data: {
    teams: Team[];
    groups: Group[];
    matches: Match[];
    knockoutMatches: KnockoutMatchData[];
  }) => {
    setTeams(data.teams);
    setGroups(data.groups);
    setMatches(data.matches);
    setKnockoutMatches(data.knockoutMatches || createInitialKnockoutMatches());
  };

  const handleLoadSlot = (slot: SaveSlot) => {
    handleLoadData(slot.data);
  };

  const handleDeleteSlot = (slotId: string) => {
    setSaveSlots((prev) => prev.filter((s) => s.id !== slotId));
  };

  // Compute live group standings for Groups A, B, C
  const standingsByGroup = useMemo(() => {
    const result: Record<GroupId, TeamStats[]> = {
      A: calculateGroupStandings('A', teams, matches),
      B: calculateGroupStandings('B', teams, matches),
      C: calculateGroupStandings('C', teams, matches),
    };
    return result;
  }, [teams, matches]);

  // Flattened standings list
  const allStandingsList = useMemo(() => {
    return [...standingsByGroup.A, ...standingsByGroup.B, ...standingsByGroup.C];
  }, [standingsByGroup]);

  // Best 2nd Place Teams comparison
  const bestSeconds = useMemo(() => {
    return calculateBestSeconds(standingsByGroup);
  }, [standingsByGroup]);

  const bestSecondTeamId = bestSeconds.length > 0 ? bestSeconds[0].teamId : undefined;

  // Update knockout bracket slots based on standings
  const knockoutDetails = useMemo(() => {
    return updateKnockoutSlots(standingsByGroup, knockoutMatches);
  }, [standingsByGroup, knockoutMatches]);

  // Final Winner Determination
  const finalMatch = knockoutDetails.knockoutMatches.find((m) => m.id === 'final');
  const championTeam = finalMatch?.winnerId ? teams.find((t) => t.id === finalMatch.winnerId) : undefined;

  // Trigger modal when champion is determined
  useEffect(() => {
    if (championTeam && finalMatch?.isPlayed) {
      setShowWinnerModal(true);
    }
  }, [championTeam, finalMatch?.isPlayed]);

  // Handlers
  const handleShuffleGroups = () => {
    const { teams: newTeams, groups: newGroups } = shuffleTeamsIntoGroups(teams);
    const newMatches = generateGroupMatches(newGroups);
    setTeams(newTeams);
    setGroups(newGroups);
    setMatches(newMatches);
    setKnockoutMatches(createInitialKnockoutMatches());
  };

  const handleUpdateTeams = (updatedTeams: Team[]) => {
    setTeams(updatedTeams);
  };

  const handleScoreChange = (matchId: string, homeScore: number | null, awayScore: number | null) => {
    setMatches((prevMatches) =>
      prevMatches.map((m) => {
        if (m.id === matchId) {
          const isPlayed = homeScore !== null && awayScore !== null;
          return { ...m, homeScore, awayScore, isPlayed };
        }
        return m;
      })
    );
  };

  const handleSimulateUnplayedGroupMatches = () => {
    setMatches((prevMatches) =>
      prevMatches.map((m) => {
        if (!m.isPlayed) {
          const hScore = Math.floor(Math.random() * 4);
          const aScore = Math.floor(Math.random() * 3);
          return { ...m, homeScore: hScore, awayScore: aScore, isPlayed: true };
        }
        return m;
      })
    );
  };

  const handleResetAllGroupScores = () => {
    setMatches((prevMatches) =>
      prevMatches.map((m) => ({ ...m, homeScore: null, awayScore: null, isPlayed: false }))
    );
    setKnockoutMatches(createInitialKnockoutMatches());
  };

  const handleKnockoutScoreChange = (
    matchId: string,
    homeScore: number | null,
    awayScore: number | null,
    homePenalty?: number | null,
    awayPenalty?: number | null
  ) => {
    setKnockoutMatches((prev) =>
      prev.map((m) => {
        if (m.id === matchId) {
          const isPlayed = homeScore !== null && awayScore !== null;
          let winnerId: string | null = null;

          if (isPlayed && m.homeTeamId && m.awayTeamId) {
            if (homeScore > awayScore) {
              winnerId = m.homeTeamId;
            } else if (awayScore > homeScore) {
              winnerId = m.awayTeamId;
            } else if (homePenalty !== undefined && awayPenalty !== undefined && homePenalty !== null && awayPenalty !== null) {
              if (homePenalty > awayPenalty) winnerId = m.homeTeamId;
              else if (awayPenalty > homePenalty) winnerId = m.awayTeamId;
            }
          }

          return {
            ...m,
            homeScore,
            awayScore,
            homePenalty,
            awayPenalty,
            isPlayed,
            winnerId,
          };
        }
        return m;
      })
    );
  };

  const handleSimulateKnockout = () => {
    // Simulate current knockout matches
    const updated = knockoutDetails.knockoutMatches.map((m) => {
      if (m.homeTeamId && m.awayTeamId) {
        let hScore = Math.floor(Math.random() * 4);
        let aScore = Math.floor(Math.random() * 4);
        let hPen = null;
        let aPen = null;

        if (hScore === aScore) {
          hPen = 5;
          aPen = 4;
        }

        const winnerId = hScore > aScore || (hPen && hPen > (aPen || 0)) ? m.homeTeamId : m.awayTeamId;

        return {
          ...m,
          homeScore: hScore,
          awayScore: aScore,
          homePenalty: hPen,
          awayPenalty: aPen,
          isPlayed: true,
          winnerId,
        };
      }
      return m;
    });

    // Handle Final if SFs played
    const sf1 = updated.find((m) => m.id === 'sf-1');
    const sf2 = updated.find((m) => m.id === 'sf-2');
    const finalM = updated.find((m) => m.id === 'final');
    const thirdM = updated.find((m) => m.id === 'third-place');

    if (sf1?.winnerId && sf2?.winnerId && finalM) {
      finalM.homeTeamId = sf1.winnerId;
      finalM.awayTeamId = sf2.winnerId;
      let fhScore = Math.floor(Math.random() * 3) + 1;
      let faScore = Math.floor(Math.random() * 3);
      finalM.homeScore = fhScore;
      finalM.awayScore = faScore;
      finalM.isPlayed = true;
      finalM.winnerId = fhScore > faScore ? sf1.winnerId : sf2.winnerId;
    }

    if (sf1?.winnerId && sf2?.winnerId && thirdM) {
      const sf1L = sf1.winnerId === sf1.homeTeamId ? sf1.awayTeamId : sf1.homeTeamId;
      const sf2L = sf2.winnerId === sf2.homeTeamId ? sf2.awayTeamId : sf2.homeTeamId;
      thirdM.homeTeamId = sf1L;
      thirdM.awayTeamId = sf2L;
      thirdM.homeScore = 2;
      thirdM.awayScore = 1;
      thirdM.isPlayed = true;
      thirdM.winnerId = sf1L;
    }

    setKnockoutMatches(updated);
  };

  const handleLoadSample = () => {
    const { teams: sTeams, groups: sGroups, matches: sMatches } = generateSampleTournamentData();
    setTeams(sTeams);
    setGroups(sGroups);
    setMatches(sMatches);
    setKnockoutMatches(createInitialKnockoutMatches());
    setActiveTab('group');
  };

  const handleResetTournament = () => {
    localStorage.removeItem(LOCAL_STORAGE_KEY);
    const initial = createInitialTeams();
    const { teams: grouped, groups: newG } = shuffleTeamsIntoGroups(initial);
    setTeams(grouped);
    setGroups(newG);
    setMatches(generateGroupMatches(newG));
    setKnockoutMatches(createInitialKnockoutMatches());
    setShowWinnerModal(false);
    setActiveTab('setup');
  };

  const playedMatchesCount = matches.filter((m) => m.isPlayed).length;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans selection:bg-emerald-500 selection:text-slate-950">

      {/* Header Bar */}
      <Header
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        onLoadSample={handleLoadSample}
        onReset={handleResetTournament}
        onSimulateAll={handleSimulateUnplayedGroupMatches}
        onOpenSaveManager={() => setIsSaveManagerOpen(true)}
        playedMatchesCount={playedMatchesCount}
        totalMatchesCount={matches.length}
        championName={championTeam?.name}
      />

      {/* Main App Container */}
      <main className="py-8 space-y-8">

        {/* Top Tournament Stats Bar */}
        <StatsOverview matches={matches} allStandings={allStandingsList} />

        {/* Tab 1: Teams & Groups Setup */}
        {activeTab === 'setup' && (
          <TeamSetup
            teams={teams}
            groups={groups}
            onUpdateTeams={handleUpdateTeams}
            onShuffleGroups={handleShuffleGroups}
            onStartTournament={() => setActiveTab('group')}
          />
        )}

        {/* Tab 2: Group Standings & Matches */}
        {activeTab === 'group' && (
          <div className="max-w-7xl mx-auto px-4 space-y-8">
            {/* Standings Tables */}
            <div>
              <h2 className="text-lg font-bold text-white mb-4 flex items-center space-x-2">
                <span className="w-2.5 h-2.5 rounded-full bg-emerald-400" />
                <span>Grup Puan Durumu (Canlı Tablo)</span>
              </h2>
              <GroupStandings
                standingsByGroup={standingsByGroup}
                bestSecondTeamId={bestSecondTeamId}
              />
            </div>

            {/* Matches List */}
            <div>
              <h2 className="text-lg font-bold text-white mb-4 flex items-center space-x-2">
                <span className="w-2.5 h-2.5 rounded-full bg-amber-400" />
                <span>Grup Maç Sonuçları Girişi (18 Maç - Rövanşlı)</span>
              </h2>
              <MatchList
                matches={matches}
                teams={teams}
                onScoreChange={handleScoreChange}
                onSimulateUnplayed={handleSimulateUnplayedGroupMatches}
                onResetAllScores={handleResetAllGroupScores}
              />
            </div>
          </div>
        )}

        {/* Tab 3: Best 2nd Place Table */}
        {activeTab === 'bestSeconds' && (
          <div className="max-w-7xl mx-auto px-4">
            <BestSecondTable bestSeconds={bestSeconds} />
          </div>
        )}

        {/* Tab 4: Knockout Stage */}
        {activeTab === 'knockout' && (
          <div className="max-w-7xl mx-auto px-4">
            <KnockoutBracket
              knockoutMatches={knockoutDetails.knockoutMatches}
              teams={teams}
              qualifiedTeams={knockoutDetails.qualifiedTeams}
              onKnockoutScoreChange={handleKnockoutScoreChange}
              championTeam={championTeam}
              onSimulateKnockout={handleSimulateKnockout}
            />
          </div>
        )}

      </main>

      {/* Champion Modal */}
      {showWinnerModal && (
        <WinnerModal
          championTeam={championTeam || null}
          onClose={() => setShowWinnerModal(false)}
          onReset={handleResetTournament}
        />
      )}

      {/* Save & Continue Manager Modal */}
      <SaveManagerModal
        isOpen={isSaveManagerOpen}
        onClose={() => setIsSaveManagerOpen(false)}
        teams={teams}
        groups={groups}
        matches={matches}
        knockoutMatches={knockoutMatches}
        onLoadData={handleLoadData}
        lastSavedAt={lastSavedAt}
        saveSlots={saveSlots}
        onSaveSlot={handleSaveSlot}
        onLoadSlot={handleLoadSlot}
        onDeleteSlot={handleDeleteSlot}
      />

      {/* Footer */}
      <footer className="border-t border-slate-900 bg-slate-950 py-6 text-center text-xs text-slate-500">
        <p>Grup & Eleme Turnuva Puan Tablosu Sistemi • Otomatik Rövanş ve Averaj Hesaplayıcı</p>
      </footer>

    </div>
  );
}

src/utils/tournament.ts:
import { Group, GroupId, KnockoutMatchData, Match, Team, TeamStats } from '../types';

export const DEFAULT_TEAM_NAMES = [
  'Kırmızı Fırtına',
  'Mavi Şimşekler',
  'Yeşil Kaplanlar',
  'Sarı Kanaryalar',
  'Kara Kartallar',
  'Turuncu Aslanlar',
  'Mor Yıldızlar',
  'Bordo Kasırga',
  'Lacivert Güneş',
];

export const TEAM_COLORS = [
  '#ef4444', // Red
  '#3b82f6', // Blue
  '#10b981', // Green
  '#eab308', // Yellow
  '#1e293b', // Dark Slate
  '#f97316', // Orange
  '#8b5cf6', // Purple
  '#881337', // Crimson/Bordo
  '#1e40af', // Navy Blue
];

/**
 * Creates 9 initial team objects
 */
export function createInitialTeams(names: string[] = DEFAULT_TEAM_NAMES): Team[] {
  return names.slice(0, 9).map((name, index) => ({
    id: `team-${index + 1}`,
    name: name.trim() || `Takım ${index + 1}`,
    shortName: (name.trim() || `T${index + 1}`).substring(0, 3).toUpperCase(),
    color: TEAM_COLORS[index % TEAM_COLORS.length],
  }));
}

/**
 * Randomly shuffles 9 teams into 3 groups of 3 teams each
 */
export function shuffleTeamsIntoGroups(teams: Team[]): { teams: Team[]; groups: Group[] } {
  const shuffled = [...teams].sort(() => Math.random() - 0.5);

  const updatedTeams: Team[] = [];
  const groups: Group[] = [
    { id: 'A', name: 'A Grubu', teamIds: [] },
    { id: 'B', name: 'B Grubu', teamIds: [] },
    { id: 'C', name: 'C Grubu', teamIds: [] },
  ];

  shuffled.forEach((team, index) => {
    const groupIndex = Math.floor(index / 3);
    const groupId = (groupIndex === 0 ? 'A' : groupIndex === 1 ? 'B' : 'C') as GroupId;

    const updatedTeam = { ...team, groupId };
    updatedTeams.push(updatedTeam);
    groups[groupIndex].teamIds.push(updatedTeam.id);
  });

  return { teams: updatedTeams, groups };
}

/**
 * Generates double round-robin matches for 3 groups of 3 teams (6 matches per group, 18 total)
 */
export function generateGroupMatches(groups: Group[]): Match[] {
  const matches: Match[] = [];
  let matchCounter = 1;

  groups.forEach((group) => {
    const ids = group.teamIds;
    if (ids.length < 3) return;

    const [t1, t2, t3] = ids;

    // Double Round Robin Fixtures (6 matches per group)
    // First Half (Round 1-3)
    const fixtures = [
      { home: t1, away: t2, round: 1 },
      { home: t2, away: t3, round: 2 },
      { home: t3, away: t1, round: 3 },
      // Second Half (Round 4-6 - Rövanş)
      { home: t2, away: t1, round: 4 },
      { home: t3, away: t2, round: 5 },
      { home: t1, away: t3, round: 6 },
    ];

    fixtures.forEach((fix) => {
      matches.push({
        id: `match-g${group.id}-${fix.round}`,
        groupId: group.id,
        stage: 'group',
        homeTeamId: fix.home,
        awayTeamId: fix.away,
        homeScore: null,
        awayScore: null,
        round: fix.round,
        isPlayed: false,
        matchNumber: matchCounter++,
      });
    });
  });

  return matches;
}

/**
 * Calculates group standings for a single group
 */
export function calculateGroupStandings(
  groupId: GroupId,
  teams: Team[],
  matches: Match[]
): TeamStats[] {
  const groupTeams = teams.filter((t) => t.groupId === groupId);
  const groupMatches = matches.filter(
    (m) => m.groupId === groupId && m.stage === 'group' && m.isPlayed && m.homeScore !== null && m.awayScore !== null
  );

  const statsMap: Record<string, TeamStats> = {};

  groupTeams.forEach((t) => {
    statsMap[t.id] = {
      teamId: t.id,
      teamName: t.name,
      shortName: t.shortName,
      color: t.color,
      groupId,
      played: 0,
      won: 0,
      drawn: 0,
      lost: 0,
      goalsFor: 0,
      goalsAgainst: 0,
      goalDifference: 0,
      points: 0,
      rank: 0,
      isQualified: false,
    };
  });

  groupMatches.forEach((m) => {
    const home = statsMap[m.homeTeamId];
    const away = statsMap[m.awayTeamId];
    if (!home || !away) return;

    const hScore = m.homeScore!;
    const aScore = m.awayScore!;

    home.played += 1;
    away.played += 1;

    home.goalsFor += hScore;
    home.goalsAgainst += aScore;
    away.goalsFor += aScore;
    away.goalsAgainst += hScore;

    if (hScore > aScore) {
      home.won += 1;
      home.points += 3;
      away.lost += 1;
    } else if (hScore < aScore) {
      away.won += 1;
      away.points += 3;
      home.lost += 1;
    } else {
      home.drawn += 1;
      home.points += 1;
      away.drawn += 1;
      away.points += 1;
    }
  });

  // Calculate Goal Difference
  Object.values(statsMap).forEach((st) => {
    st.goalDifference = st.goalsFor - st.goalsAgainst;
  });

  // Sort standings: Points -> Goal Difference -> Goals For -> Alphabetical Name
  const sorted = Object.values(statsMap).sort((a, b) => {
    if (b.points !== a.points) return b.points - a.points;
    if (b.goalDifference !== a.goalDifference) return b.goalDifference - a.goalDifference;
    if (b.goalsFor !== a.goalsFor) return b.goalsFor - a.goalsFor;
    return a.teamName.localeCompare(b.teamName, 'tr');
  });

  // Assign Ranks
  sorted.forEach((st, idx) => {
    st.rank = idx + 1;
  });

  return sorted;
}

/**
 * Calculates Best 2nd Place Team across Groups A, B, C
 */
export function calculateBestSeconds(allStandings: Record<GroupId, TeamStats[]>): TeamStats[] {
  const seconds: TeamStats[] = [];

  (['A', 'B', 'C'] as GroupId[]).forEach((gid) => {
    const gStandings = allStandings[gid];
    if (gStandings && gStandings.length >= 2) {
      seconds.push({ ...gStandings[1] }); // 2nd placed team
    }
  });

  // Sort 2nd place teams: Points -> Goal Difference -> Goals For -> Alphabetical
  seconds.sort((a, b) => {
    if (b.points !== a.points) return b.points - a.points;
    if (b.goalDifference !== a.goalDifference) return b.goalDifference - a.goalDifference;
    if (b.goalsFor !== a.goalsFor) return b.goalsFor - a.goalsFor;
    return a.teamName.localeCompare(b.teamName, 'tr');
  });

  return seconds;
}

/**
 * Initial empty Knockout matches setup (2 Semi-Finals, 1 Final, 1 3rd-Place)
 */
export function createInitialKnockoutMatches(): KnockoutMatchData[] {
  return [
    {
      id: 'sf-1',
      title: 'Yarı Final 1',
      stage: 'semi-final',
      homeTeamId: null,
      awayTeamId: null,
      homeScore: null,
      awayScore: null,
      winnerId: null,
      isPlayed: false,
      slotHomeDescription: '1. Yarı Finalist (Grup Lideri)',
      slotAwayDescription: 'En İyi 2. Takım',
    },
    {
      id: 'sf-2',
      title: 'Yarı Final 2',
      stage: 'semi-final',
      homeTeamId: null,
      awayTeamId: null,
      homeScore: null,
      awayScore: null,
      winnerId: null,
      isPlayed: false,
      slotHomeDescription: '2. Yarı Finalist (Grup Lideri)',
      slotAwayDescription: '3. Yarı Finalist (Grup Lideri)',
    },
    {
      id: 'third-place',
      title: 'Üçüncülük Maçı',
      stage: 'third-place',
      homeTeamId: null,
      awayTeamId: null,
      homeScore: null,
      awayScore: null,
      winnerId: null,
      isPlayed: false,
      slotHomeDescription: 'Yarı Final 1 Mağlubu',
      slotAwayDescription: 'Yarı Final 2 Mağlubu',
    },
    {
      id: 'final',
      title: 'ŞAMPİYONLUK FİNALİ',
      stage: 'final',
      homeTeamId: null,
      awayTeamId: null,
      homeScore: null,
      awayScore: null,
      winnerId: null,
      isPlayed: false,
      slotHomeDescription: 'Yarı Final 1 Galibi',
      slotAwayDescription: 'Yarı Final 2 Galibi',
    },
  ];
}

/**
 * Automatically updates Knockout slots based on group winners & best second team
 */
export function updateKnockoutSlots(
  allStandings: Record<GroupId, TeamStats[]>,
  existingKnockouts: KnockoutMatchData[]
): {
  knockoutMatches: KnockoutMatchData[];
  qualifiedTeams: TeamStats[];
  bestSecondTeam: TeamStats | null;
  groupWinners: TeamStats[];
} {
  const groupWinners: TeamStats[] = [];
  (['A', 'B', 'C'] as GroupId[]).forEach((gid) => {
    const groupStandings = allStandings[gid];
    if (groupStandings && groupStandings.length > 0) {
      groupWinners.push({ ...groupStandings[0] });
    }
  });

  // Sort group winners by performance (Points -> GD -> GF) to seed semi-finals
  groupWinners.sort((a, b) => {
    if (b.points !== a.points) return b.points - a.points;
    if (b.goalDifference !== a.goalDifference) return b.goalDifference - a.goalDifference;
    if (b.goalsFor !== a.goalsFor) return b.goalsFor - a.goalsFor;
    return a.teamName.localeCompare(b.teamName, 'tr');
  });

  const bestSeconds = calculateBestSeconds(allStandings);
  const bestSecondTeam = bestSeconds.length > 0 ? bestSeconds[0] : null;

  // Qualified teams list (3 winners + 1 best second)
  const qualifiedTeams: TeamStats[] = [];
  groupWinners.forEach((w) => {
    w.isQualified = true;
    w.qualificationReason = `${w.groupId} Grubu Lideri`;
    qualifiedTeams.push(w);
  });

  if (bestSecondTeam) {
    bestSecondTeam.isQualified = true;
    bestSecondTeam.qualificationReason = `En İyi 2. Takım (${bestSecondTeam.groupId} Grubu)`;
    qualifiedTeams.push(bestSecondTeam);
  }

  // Update Semi Final slots
  const updatedKnockouts = existingKnockouts.map((km) => {
    const copy = { ...km };

    if (km.id === 'sf-1') {
      // Best Group Winner vs Best 2nd Place Team
      copy.homeTeamId = groupWinners[0]?.teamId || null;
      copy.awayTeamId = bestSecondTeam?.teamId || null;
      copy.slotHomeDescription = groupWinners[0]
        ? `${groupWinners[0].teamName} (${groupWinners[0].groupId} Grubu 1.si)`
        : 'En İyi Grup Lideri';
      copy.slotAwayDescription = bestSecondTeam
        ? `${bestSecondTeam.teamName} (En İyi 2.)`
        : 'En İyi 2. Takım';
    } else if (km.id === 'sf-2') {
      // 2nd Best Winner vs 3rd Best Winner
      copy.homeTeamId = groupWinners[1]?.teamId || null;
      copy.awayTeamId = groupWinners[2]?.teamId || null;
      copy.slotHomeDescription = groupWinners[1]
        ? `${groupWinners[1].teamName} (${groupWinners[1].groupId} Grubu 1.si)`
        : '2. En İyi Lider';
      copy.slotAwayDescription = groupWinners[2]
        ? `${groupWinners[2].teamName} (${groupWinners[2].groupId} Grubu 1.si)`
        : '3. En İyi Lider';
    }

    return copy;
  });

  // Process Semi Final winners/losers into Final and 3rd Place Match
  const sf1 = updatedKnockouts.find((m) => m.id === 'sf-1');
  const sf2 = updatedKnockouts.find((m) => m.id === 'sf-2');

  const finalMatch = updatedKnockouts.find((m) => m.id === 'final');
  const thirdMatch = updatedKnockouts.find((m) => m.id === 'third-place');

  if (sf1 && sf2) {
    if (sf1.isPlayed && sf1.winnerId) {
      const sf1LoserId = sf1.winnerId === sf1.homeTeamId ? sf1.awayTeamId : sf1.homeTeamId;
      if (finalMatch) finalMatch.homeTeamId = sf1.winnerId;
      if (thirdMatch) thirdMatch.homeTeamId = sf1LoserId;
    }

    if (sf2.isPlayed && sf2.winnerId) {
      const sf2LoserId = sf2.winnerId === sf2.homeTeamId ? sf2.awayTeamId : sf2.homeTeamId;
      if (finalMatch) finalMatch.awayTeamId = sf2.winnerId;
      if (thirdMatch) thirdMatch.awayTeamId = sf2LoserId;
    }
  }

  return {
    knockoutMatches: updatedKnockouts,
    qualifiedTeams,
    bestSecondTeam,
    groupWinners,
  };
}

/**
 * Generates sample data with populated team names & played group matches for instant demoing
 */
export function generateSampleTournamentData(): {
  teams: Team[];
  groups: Group[];
  matches: Match[];
} {
  const sampleNames = [
    'Anadolu Kartalları',
    'Boğaziçi Aslanları',
    'Ege Fırtınası',
    'Karadeniz Kaplanları',
    'Toros Kaplanları',
    'Akdeniz Rüzgarı',
    'Marmara Yıldızları',
    'Kafkas Güneşi',
    'Güneydoğu Şimşekleri',
  ];

  const teams = createInitialTeams(sampleNames);
  const { teams: groupedTeams, groups } = shuffleTeamsIntoGroups(teams);
  const matches = generateGroupMatches(groups);

  // Fill in realistic group match scores
  const sampleScores = [
    [2, 1], [0, 0], [3, 1], [1, 2], [2, 2], [1, 0],
    [3, 0], [1, 1], [2, 3], [0, 1], [4, 2], [2, 0],
    [1, 0], [2, 1], [3, 3], [1, 2], [0, 2], [2, 1]
  ];

  matches.forEach((m, idx) => {
    const pair = sampleScores[idx % sampleScores.length];
    m.homeScore = pair[0];
    m.awayScore = pair[1];
    m.isPlayed = true;
  });

  return { teams: groupedTeams, groups, matches };
}

