import React, { useState, useRef } from 'react';
import {
  Save,
  Download,
  Upload,
  Clock,
  CheckCircle2,
  Trash2,
  Plus,
  HardDrive,
  X,
  ShieldCheck,
  FileJson,
  RotateCcw,
  Info,
  Calendar,
  Sparkles,
} from 'lucide-react';
import { Group, KnockoutMatchData, Match, SaveSlot, Team } from '../types';

interface SaveManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  teams: Team[];
  groups: Group[];
  matches: Match[];
  knockoutMatches: KnockoutMatchData[];
  onLoadData: (data: {
    teams: Team[];
    groups: Group[];
    matches: Match[];
    knockoutMatches: KnockoutMatchData[];
  }) => void;
  lastSavedAt: Date | null;
  saveSlots: SaveSlot[];
  onSaveSlot: (name: string) => void;
  onLoadSlot: (slot: SaveSlot) => void;
  onDeleteSlot: (slotId: string) => void;
}

export const SaveManagerModal: React.FC<SaveManagerModalProps> = ({
  isOpen,
  onClose,
  teams,
  groups,
  matches,
  knockoutMatches,
  onLoadData,
  lastSavedAt,
  saveSlots,
  onSaveSlot,
  onLoadSlot,
  onDeleteSlot,
}) => {
  const [newSlotName, setNewSlotName] = useState('');
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!isOpen) return null;

  const showToast = (msg: string) => {
    setToastMessage(msg);
    setTimeout(() => setToastMessage(null), 3500);
  };

  const playedMatchesCount = matches.filter((m) => m.isPlayed).length;

  // Export current state to JSON file
  const handleExportJson = () => {
    const payload = {
      version: '1.0',
      exportedAt: new Date().toISOString(),
      appName: 'Turnuva Puan Tablosu',
      data: {
        teams,
        groups,
        matches,
        knockoutMatches,
      },
    };

    const dataStr = 'data:text/json;charset=utf-8,' + encodeURIComponent(JSON.stringify(payload, null, 2));
    const downloadAnchor = document.createElement('a');
    const dateStr = new Date().toISOString().slice(0, 10);
    downloadAnchor.setAttribute('href', dataStr);
    downloadAnchor.setAttribute('download', `turnuva_yedek_${dateStr}.json`);
    document.body.appendChild(downloadAnchor);
    downloadAnchor.click();
    downloadAnchor.remove();

    showToast(' Turnuva yedeği .json dosyası olarak indirildi!');
  };

  // Import from JSON file
  const handleImportJson = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const content = event.target?.result as string;
        const parsed = JSON.parse(content);

        const tournamentData = parsed.data || parsed;
        if (
          Array.isArray(tournamentData.teams) &&
          Array.isArray(tournamentData.groups) &&
          Array.isArray(tournamentData.matches)
        ) {
          onLoadData({
            teams: tournamentData.teams,
            groups: tournamentData.groups,
            matches: tournamentData.matches,
            knockoutMatches: tournamentData.knockoutMatches || [],
          });
          showToast(' Turnuva verileri dosyadan başarıyla yüklendi!');
          if (fileInputRef.current) fileInputRef.current.value = '';
        } else {
          alert('Geçersiz yedek dosyası formatı! Lütfen geçerli bir turnuva JSON dosyası seçin.');
        }
      } catch (err) {
        console.error(err);
        alert('Dosya okunurken bir hata oluştu. Lütfen dosya formatını kontrol edin.');
      }
    };
    reader.readAsText(file);
  };

  const handleCreateSlot = (e: React.FormEvent) => {
    e.preventDefault();
    const name = newSlotName.trim() || `Yedek (${new Date().toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })})`;
    onSaveSlot(name);
    setNewSlotName('');
    showToast(`"${name}" adıyla kayıt noktası oluşturuldu!`);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-slate-900 border border-slate-800 rounded-2xl w-full max-w-2xl max-h-[90vh] flex flex-col shadow-2xl shadow-emerald-950/40 text-slate-100 overflow-hidden">

        {/* Header */}
        <div className="p-6 border-b border-slate-800/80 flex items-center justify-between bg-gradient-to-r from-slate-900 via-slate-900 to-slate-800">
          <div className="flex items-center space-x-3">
            <div className="p-2.5 bg-emerald-500/10 border border-emerald-500/20 rounded-xl text-emerald-400">
              <HardDrive className="w-6 h-6" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <span>Kaydet & Sonraki Gün Devam Et</span>
              </h2>
              <p className="text-xs text-slate-400">
                Turnuva ilerlemenizi tarayıcıda saklayın, yedekleyin veya başka cihaza aktarın
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="p-2 text-slate-400 hover:text-white bg-slate-800 hover:bg-slate-700 rounded-lg transition-colors cursor-pointer"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Scrollable Content */}
        <div className="p-6 overflow-y-auto space-y-6">

          {/* Toast Notification */}
          {toastMessage && (
            <div className="bg-emerald-500/15 border border-emerald-500/40 text-emerald-300 p-3 rounded-xl text-xs font-medium flex items-center space-x-2 animate-in slide-in-from-top duration-200">
              <CheckCircle2 className="w-4 h-4 text-emerald-400 shrink-0" />
              <span>{toastMessage}</span>
            </div>
          )}

          {/* Automatic Save Status */}
          <div className="bg-slate-950/80 border border-emerald-500/30 rounded-xl p-4 flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
            <div className="flex items-start space-x-3">
              <div className="relative mt-1">
                <span className="flex h-3 w-3">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                  <span className="relative inline-flex rounded-full h-3 w-3 bg-emerald-500"></span>
                </span>
              </div>
              <div>
                <div className="flex items-center space-x-2">
                  <span className="text-sm font-semibold text-white">Anlık Otomatik Kayıt Aktif</span>
                  <span className="text-[10px] bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 px-2 py-0.5 rounded-full font-mono">
                    LocalStorage
                  </span>
                </div>
                <p className="text-xs text-slate-400 mt-0.5">
                  Girdiğiniz her skor ve yaptığınız her değişiklik otomatik olarak kaydedilir. Yarın bu sayfaya aynı tarayıcıdan girdiğinizde kaldığınız yerden devam edebilirsiniz.
                </p>
              </div>
            </div>

            <div className="text-right shrink-0 self-end sm:self-center">
              <div className="text-[11px] text-slate-500 flex items-center justify-end space-x-1">
                <Clock className="w-3 h-3 text-slate-400" />
                <span>Son Otomatik Kayıt:</span>
              </div>
              <div className="text-xs font-mono font-medium text-emerald-400 mt-0.5">
                {lastSavedAt
                  ? lastSavedAt.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit', second: '2-digit' })
                  : 'Şimdi'}
              </div>
            </div>
          </div>

          {/* Backup & Import Actions */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">

            {/* Export File */}
            <div className="bg-slate-800/50 border border-slate-700/80 rounded-xl p-4 hover:border-slate-600 transition-all flex flex-col justify-between">
              <div>
                <div className="flex items-center space-x-2 text-white font-medium text-sm mb-1">
                  <FileJson className="w-4 h-4 text-amber-400" />
                  <span>Turnuvayı Dosyaya İndir</span>
                </div>
                <p className="text-xs text-slate-400 mb-4">
                  Turnuva verilerini bilgisayarınıza veya telefonunuza `.json` dosyası olarak indirin. Başka cihazda devam etmek için idealdir.
                </p>
              </div>
              <button
                onClick={handleExportJson}
                className="w-full py-2 px-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-xs font-medium flex items-center justify-center space-x-2 transition-colors cursor-pointer"
              >
                <Download className="w-4 h-4 text-emerald-400" />
                <span>Yedek Dosyası İndir (.json)</span>
              </button>
            </div>

            {/* Import File */}
            <div className="bg-slate-800/50 border border-slate-700/80 rounded-xl p-4 hover:border-slate-600 transition-all flex flex-col justify-between">
              <div>
                <div className="flex items-center space-x-2 text-white font-medium text-sm mb-1">
                  <Upload className="w-4 h-4 text-cyan-400" />
                  <span>Yedek Dosyasından Yükle</span>
                </div>
                <p className="text-xs text-slate-400 mb-4">
                  Daha önce indirdiğiniz `.json` yedek dosyasını yükleyerek eski bir turnuvayı veya başka bir cihazdaki veriyi açın.
                </p>
              </div>
              <div>
                <input
                  type="file"
                  accept=".json"
                  ref={fileInputRef}
                  onChange={handleImportJson}
                  className="hidden"
                />
                <button
                  onClick={() => fileInputRef.current?.click()}
                  className="w-full py-2 px-3 bg-slate-700 hover:bg-slate-600 text-white rounded-lg text-xs font-medium flex items-center justify-center space-x-2 transition-colors cursor-pointer"
                >
                  <Upload className="w-4 h-4 text-cyan-400" />
                  <span>Dosya Seç & Yükle</span>
                </button>
              </div>
            </div>

          </div>

          {/* Create Manual Save Snapshot */}
          <div className="bg-slate-800/30 border border-slate-700/60 rounded-xl p-4 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-sm font-semibold text-white flex items-center space-x-2">
                <Sparkles className="w-4 h-4 text-amber-400" />
                <span>Özel Kayıt Noktası (Snapshot) Oluştur</span>
              </span>
              <span className="text-[11px] text-slate-400">Geri dönmek üzere aşama kaydet</span>
            </div>

            <form onSubmit={handleCreateSlot} className="flex items-center gap-2">
              <input
                type="text"
                placeholder="Örn: 1. Gün Sonu - Grup Maçları Yarısı"
                value={newSlotName}
                onChange={(e) => setNewSlotName(e.target.value)}
                className="flex-1 bg-slate-950 border border-slate-700 rounded-lg px-3 py-2 text-xs text-slate-100 placeholder-slate-500 focus:outline-none focus:border-emerald-500"
              />
              <button
                type="submit"
                className="px-4 py-2 bg-emerald-600 hover:bg-emerald-500 text-white font-medium text-xs rounded-lg flex items-center space-x-1.5 shadow-md shadow-emerald-950/30 transition-all cursor-pointer whitespace-nowrap"
              >
                <Plus className="w-4 h-4" />
                <span>Kayıt Noktası Ekle</span>
              </button>
            </form>
          </div>

          {/* Saved Snapshots List */}
          <div>
            <h3 className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3 flex items-center justify-between">
              <span>Kayıtlı Anlık Görüntüler ({saveSlots.length})</span>
              <span className="text-[10px] text-slate-500 font-normal">Tarayıcıda Saklananlar</span>
            </h3>

            {saveSlots.length === 0 ? (
              <div className="p-6 bg-slate-950/40 border border-dashed border-slate-800 rounded-xl text-center text-xs text-slate-500">
                Henüz özel kayıt noktası oluşturulmadı. Yukarıdaki kutucuğu kullanarak turnuva aşamalarınızı isim vererek saklayabilirsiniz.
              </div>
            ) : (
              <div className="space-y-2 max-h-48 overflow-y-auto pr-1">
                {saveSlots.map((slot) => (
                  <div
                    key={slot.id}
                    className="p-3 bg-slate-800/60 border border-slate-700/80 hover:border-slate-600 rounded-xl flex items-center justify-between gap-3 text-xs"
                  >
                    <div className="min-w-0 flex-1">
                      <div className="font-semibold text-white truncate">{slot.name}</div>
                      <div className="flex items-center space-x-3 text-[11px] text-slate-400 mt-1">
                        <span className="flex items-center space-x-1">
                          <Calendar className="w-3 h-3 text-slate-500" />
                          <span>{slot.savedAt}</span>
                        </span>
                        <span className="text-emerald-400 font-mono">
                          {slot.playedCount}/{slot.totalCount} Maç
                        </span>
                      </div>
                    </div>

                    <div className="flex items-center space-x-2 shrink-0">
                      <button
                        onClick={() => {
                          onLoadSlot(slot);
                          showToast(`"${slot.name}" kaydı geri yüklendi!`);
                        }}
                        className="px-2.5 py-1.5 bg-emerald-600/20 hover:bg-emerald-600 text-emerald-300 hover:text-white border border-emerald-500/30 rounded-lg text-xs font-medium flex items-center space-x-1 transition-colors cursor-pointer"
                        title="Bu kaydı yükle"
                      >
                        <RotateCcw className="w-3.5 h-3.5" />
                        <span>Yükle</span>
                      </button>

                      <button
                        onClick={() => {
                          if (confirm(`"${slot.name}" kayıt noktasını silmek istediğinize emin misiniz?`)) {
                            onDeleteSlot(slot.id);
                            showToast('Kayıt noktası silindi.');
                          }
                        }}
                        className="p-1.5 bg-slate-900 hover:bg-rose-950/50 text-slate-400 hover:text-rose-400 border border-slate-700 hover:border-rose-800/50 rounded-lg transition-colors cursor-pointer"
                        title="Sil"
                      >
                        <Trash2 className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Quick Guidance Info */}
          <div className="bg-slate-950/90 border border-slate-800 rounded-xl p-4 text-xs text-slate-400 space-y-2">
            <div className="flex items-center space-x-2 text-emerald-400 font-semibold">
              <ShieldCheck className="w-4 h-4" />
              <span>Veri Güvenliği Bilgilendirmesi</span>
            </div>
            <ul className="list-disc list-inside space-y-1 text-[11px] leading-relaxed text-slate-300">
              <li>
                <strong>Otomatik Koruma:</strong> Tarayıcıyı kapatsanız veya yarın geri dönseniz bile tüm verileriniz en son haliyle saklanır.
              </li>
              <li>
                <strong>Farklı Cihazlar:</strong> Eğer turnuvayı başka bir bilgisayardan veya telefondan sürdürmek isterseniz <strong>"Yedek Dosyası İndir (.json)"</strong> yapıp yeni cihazda <strong>"Dosya Seç & Yükle"</strong> seçeneğini kullanabilirsiniz.
              </li>
            </ul>
          </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-800/80 bg-slate-950 flex items-center justify-between">
          <div className="text-xs text-slate-500 flex items-center space-x-1.5">
            <Info className="w-3.5 h-3.5 text-slate-400" />
            <span>Kaldığınız yeri kaydetmek için ek işlem yapmanıza gerek yoktur.</span>
          </div>

          <button
            onClick={onClose}
            className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-lg text-xs font-medium transition-colors cursor-pointer"
          >
            Tamam / Kapat
          </button>
        </div>

      </div>
    </div>
  );
};

src/components/WinnerModal.tsx:
import React, { useEffect } from 'react';
import confetti from 'canvas-confetti';
import { Team } from '../types';
import { Trophy, Sparkles, X, RotateCcw } from 'lucide-react';

interface WinnerModalProps {
  championTeam: Team | null;
  onClose: () => void;
  onReset: () => void;
}

export const WinnerModal: React.FC<WinnerModalProps> = ({ championTeam, onClose, onReset }) => {
  useEffect(() => {
    if (championTeam) {
      // Fire confetti animation
      const duration = 3 * 1000;
      const animationEnd = Date.now() + duration;
      const defaults = { startVelocity: 30, spread: 360, ticks: 60, zIndex: 100 };

      const interval: any = setInterval(function () {
        const timeLeft = animationEnd - Date.now();

        if (timeLeft <= 0) {
          return clearInterval(interval);
        }

        const particleCount = 50 * (timeLeft / duration);
        confetti({ ...defaults, particleCount, origin: { x: 0.2, y: 0.5 } });
        confetti({ ...defaults, particleCount, origin: { x: 0.8, y: 0.5 } });
      }, 250);

      return () => clearInterval(interval);
    }
  }, [championTeam]);

  if (!championTeam) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md animate-fade-in">
      <div className="bg-slate-900 border-2 border-amber-500/80 rounded-3xl max-w-md w-full p-8 shadow-2xl relative overflow-hidden text-center space-y-6">

        {/* Glow Effects */}
        <div className="absolute -top-12 -left-12 w-40 h-40 bg-amber-500/20 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute -bottom-12 -right-12 w-40 h-40 bg-emerald-500/20 rounded-full blur-3xl pointer-events-none" />

        {/* Close Button */}
        <button
          onClick={onClose}
          className="absolute top-4 right-4 text-slate-400 hover:text-white p-2 rounded-full hover:bg-slate-800 transition-colors cursor-pointer"
        >
          <X className="w-5 h-5" />
        </button>

        {/* Trophy Visual */}
        <div className="relative inline-block">
          <div className="w-24 h-24 rounded-3xl bg-gradient-to-tr from-amber-500 via-yellow-400 to-amber-600 p-0.5 shadow-2xl shadow-amber-500/40 mx-auto flex items-center justify-center animate-bounce">
            <div className="w-full h-full bg-slate-950 rounded-[22px] flex items-center justify-center text-amber-400">
              <Trophy className="w-12 h-12" />
            </div>
          </div>
          <Sparkles className="w-6 h-6 text-yellow-300 absolute -top-2 -right-2 animate-spin" />
        </div>

        {/* Title & Champion */}
        <div className="space-y-2">
          <div className="text-xs uppercase font-mono font-black text-amber-400 tracking-widest flex items-center justify-center space-x-1">
            <span>🏆 TURNUVA ŞAMPİYONU 🏆</span>
          </div>
          <h2 className="text-3xl font-black text-white tracking-tight">
            {championTeam.name}
          </h2>
          <p className="text-xs text-slate-300 leading-relaxed px-4">
            Bütün rakiplerini mağlup ederek büyük turnuvanın birincisi ve altın kupanın sahibi oldu!
          </p>
        </div>

        {/* Actions */}
        <div className="pt-2 flex flex-col sm:flex-row gap-3">
          <button
            onClick={onClose}
            className="flex-1 py-3 bg-gradient-to-r from-amber-500 to-emerald-500 hover:from-amber-400 hover:to-emerald-400 text-slate-950 font-bold rounded-xl text-sm shadow-lg shadow-amber-900/30 transition-all cursor-pointer"
          >
            Kupayı Kutla! 🎉
          </button>

          <button
            onClick={onReset}
            className="py-3 px-4 bg-slate-800 hover:bg-slate-700 text-slate-300 font-semibold rounded-xl text-sm flex items-center justify-center space-x-1.5 transition-colors cursor-pointer"
          >
            <RotateCcw className="w-4 h-4" />
            <span>Yeni Turnuva</span>
          </button>
        </div>

      </div>
    </div>
  );
};

src/components/KnockoutBracket.tsx:
import React from 'react';
import { KnockoutMatchData, Team, TeamStats } from '../types';
import { Trophy, Award, Sparkles, AlertCircle, CheckCircle } from 'lucide-react';

interface KnockoutBracketProps {
  knockoutMatches: KnockoutMatchData[];
  teams: Team[];
  qualifiedTeams: TeamStats[];
  onKnockoutScoreChange: (
    matchId: string,
    homeScore: number | null,
    awayScore: number | null,
    homePenalty?: number | null,
    awayPenalty?: number | null
  ) => void;
  championTeam?: Team;
  onSimulateKnockout: () => void;
}

export const KnockoutBracket: React.FC<KnockoutBracketProps> = ({
  knockoutMatches,
  teams,
  qualifiedTeams,
  onKnockoutScoreChange,
  championTeam,
  onSimulateKnockout,
}) => {
  const getTeam = (teamId: string | null) => {
    if (!teamId) return null;
    return teams.find((t) => t.id === teamId) || null;
  };

  const sf1 = knockoutMatches.find((m) => m.id === 'sf-1');
  const sf2 = knockoutMatches.find((m) => m.id === 'sf-2');
  const thirdPlace = knockoutMatches.find((m) => m.id === 'third-place');
  const finalMatch = knockoutMatches.find((m) => m.id === 'final');

  const renderMatchCard = (match: KnockoutMatchData | undefined, isFinal: boolean = false) => {
    if (!match) return null;

    const homeTeam = getTeam(match.homeTeamId);
    const awayTeam = getTeam(match.awayTeamId);

    const isDraw =
      match.homeScore !== null &&
      match.awayScore !== null &&
      match.homeScore === match.awayScore;

    return (
      <div
        className={`bg-slate-900 border rounded-2xl p-5 shadow-2xl relative overflow-hidden transition-all ${
          isFinal
            ? 'border-amber-500/60 bg-gradient-to-b from-slate-900 via-amber-950/20 to-slate-900 shadow-amber-950/40 ring-1 ring-amber-500/30'
            : match.isPlayed
            ? 'border-emerald-500/40 bg-slate-900'
            : 'border-slate-800'
        }`}
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-slate-800 pb-3 mb-4">
          <div className="flex items-center space-x-2">
            {isFinal ? (
              <Trophy className="w-5 h-5 text-amber-400 animate-bounce" />
            ) : (
              <Award className="w-4 h-4 text-emerald-400" />
            )}
            <span
              className={`font-bold text-sm tracking-wide ${
                isFinal ? 'text-amber-400 uppercase font-black' : 'text-slate-100'
              }`}
            >
              {match.title}
            </span>
          </div>

          {match.isPlayed ? (
            <span className="text-[10px] bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 px-2.5 py-0.5 rounded-full font-bold flex items-center gap-1">
              <CheckCircle className="w-3 h-3" /> Sonuçlandı
            </span>
          ) : (
            <span className="text-[10px] bg-slate-800 text-slate-400 px-2 py-0.5 rounded-full font-mono">
              Bekliyor
            </span>
          )}
        </div>

        {/* Teams and Scores */}
        <div className="space-y-3">

          {/* Home Team Row */}
          <div
            className={`flex items-center justify-between p-3 rounded-xl border transition-colors ${
              match.winnerId && match.winnerId === match.homeTeamId
                ? 'bg-emerald-950/30 border-emerald-500/50 text-white font-bold'
                : 'bg-slate-950/80 border-slate-800 text-slate-300'
            }`}
          >
            <div className="flex items-center space-x-3 truncate">
              {homeTeam ? (
                <>
                  <span
                    className="w-3.5 h-3.5 rounded-full shrink-0 shadow-sm"
                    style={{ backgroundColor: homeTeam.color || '#3b82f6' }}
                  />
                  <span className="font-bold text-sm truncate">{homeTeam.name}</span>
                </>
              ) : (
                <span className="text-xs text-slate-500 italic">
                  {match.slotHomeDescription || 'TBD'}
                </span>
              )}
            </div>

            <input
              type="number"
              min={0}
              max={20}
              disabled={!match.homeTeamId}
              value={match.homeScore !== null ? match.homeScore : ''}
              onChange={(e) => {
                const val = e.target.value === '' ? null : parseInt(e.target.value, 10);
                onKnockoutScoreChange(
                  match.id,
                  isNaN(val as number) ? null : val,
                  match.awayScore,
                  match.homePenalty,
                  match.awayPenalty
                );
              }}
              placeholder="-"
              className="w-10 h-10 bg-slate-900 text-amber-400 font-mono font-black text-center text-lg rounded-lg border border-slate-700 focus:outline-none focus:border-amber-500 disabled:opacity-30"
            />
          </div>

          {/* Away Team Row */}
          <div
            className={`flex items-center justify-between p-3 rounded-xl border transition-colors ${
              match.winnerId && match.winnerId === match.awayTeamId
                ? 'bg-emerald-950/30 border-emerald-500/50 text-white font-bold'
                : 'bg-slate-950/80 border-slate-800 text-slate-300'
            }`}
          >
            <div className="flex items-center space-x-3 truncate">
              {awayTeam ? (
                <>
                  <span
                    className="w-3.5 h-3.5 rounded-full shrink-0 shadow-sm"
                    style={{ backgroundColor: awayTeam.color || '#3b82f6' }}
                  />
                  <span className="font-bold text-sm truncate">{awayTeam.name}</span>
                </>
              ) : (
                <span className="text-xs text-slate-500 italic">
                  {match.slotAwayDescription || 'TBD'}
                </span>
              )}
            </div>

            <input
              type="number"
              min={0}
              max={20}
              disabled={!match.awayTeamId}
              value={match.awayScore !== null ? match.awayScore : ''}
              onChange={(e) => {
                const val = e.target.value === '' ? null : parseInt(e.target.value, 10);
                onKnockoutScoreChange(
                  match.id,
                  match.homeScore,
                  isNaN(val as number) ? null : val,
                  match.homePenalty,
                  match.awayPenalty
                );
              }}
              placeholder="-"
              className="w-10 h-10 bg-slate-900 text-amber-400 font-mono font-black text-center text-lg rounded-lg border border-slate-700 focus:outline-none focus:border-amber-500 disabled:opacity-30"
            />
          </div>

        </div>

        {/* Penalty Shootout section if draw */}
        {isDraw && (
          <div className="mt-4 pt-3 border-t border-amber-500/30 bg-amber-950/20 rounded-xl p-3 space-y-2">
            <div className="flex items-center space-x-1.5 text-xs text-amber-400 font-bold">
              <AlertCircle className="w-3.5 h-3.5" />
              <span>Beraberlik! Penaltı Atışları:</span>
            </div>
            <div className="grid grid-cols-2 gap-3 text-xs">
              <div className="flex items-center justify-between bg-slate-950 p-2 rounded-lg border border-slate-800">
                <span className="text-slate-300 font-medium truncate">{homeTeam?.shortName || 'Ev'}</span>
                <input
                  type="number"
                  min={0}
                  max={20}
                  value={match.homePenalty !== null ? match.homePenalty : ''}
                  onChange={(e) => {
                    const val = e.target.value === '' ? null : parseInt(e.target.value, 10);
                    onKnockoutScoreChange(
                      match.id,
                      match.homeScore,
                      match.awayScore,
                      isNaN(val as number) ? null : val,
                      match.awayPenalty
                    );
                  }}
                  placeholder="P"
                  className="w-8 h-8 bg-slate-900 text-emerald-400 font-mono font-bold text-center rounded border border-slate-700 focus:outline-none focus:border-emerald-500"
                />
              </div>

              <div className="flex items-center justify-between bg-slate-950 p-2 rounded-lg border border-slate-800">
                <span className="text-slate-300 font-medium truncate">{awayTeam?.shortName || 'Dep'}</span>
                <input
                  type="number"
                  min={0}
                  max={20}
                  value={match.awayPenalty !== null ? match.awayPenalty : ''}
                  onChange={(e) => {
                    const val = e.target.value === '' ? null : parseInt(e.target.value, 10);
                    onKnockoutScoreChange(
                      match.id,
                      match.homeScore,
                      match.awayScore,
                      match.homePenalty,
                      isNaN(val as number) ? null : val
                    );
                  }}
                  placeholder="P"
                  className="w-8 h-8 bg-slate-900 text-emerald-400 font-mono font-bold text-center rounded border border-slate-700 focus:outline-none focus:border-emerald-500"
                />
              </div>
            </div>
          </div>
        )}

        {/* Winner Tag */}
        {match.winnerId && (
          <div className="mt-3 text-center bg-emerald-500/10 border border-emerald-500/30 p-2 rounded-xl text-xs text-emerald-400 font-bold flex items-center justify-center space-x-1">
            <Trophy className="w-3.5 h-3.5" />
            <span>Tur Atlayan: {getTeam(match.winnerId)?.name}</span>
          </div>
        )}

      </div>
    );
  };

  return (
    <div className="space-y-8 max-w-7xl mx-auto px-4">

      {/* Banner / Qualified teams summary */}
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-xl space-y-4">
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
          <div>
            <div className="flex items-center space-x-2 text-amber-400 font-bold text-sm">
              <Sparkles className="w-4 h-4" />
              <span>Yarı Finalist 4 Takım</span>
            </div>
            <h2 className="text-xl font-bold text-white tracking-tight">
              Eleme Turnuvası Ağacı & Şampiyonluk Aşaması
            </h2>
          </div>

          <button
            onClick={onSimulateKnockout}
            className="px-4 py-2 bg-gradient-to-r from-amber-500 to-emerald-500 hover:from-amber-400 hover:to-emerald-400 text-slate-950 font-bold rounded-xl text-xs flex items-center space-x-2 shadow-lg shadow-amber-900/30 transition-all cursor-pointer"
          >
            <Sparkles className="w-4 h-4" />
            <span>Eleme Maçlarını Otomatik Tamamla</span>
          </button>
        </div>

        {/* Qualified Teams Badges */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 pt-2">
          {qualifiedTeams.map((qt) => (
            <div
              key={qt.teamId}
              className="bg-slate-950 p-3 rounded-xl border border-slate-800 flex items-center space-x-3"
            >
              <div
                className="w-3.5 h-3.5 rounded-full shrink-0 shadow-sm"
                style={{ backgroundColor: qt.color || '#3b82f6' }}
              />
              <div className="truncate">
                <div className="font-bold text-white text-xs truncate">{qt.teamName}</div>
                <div className="text-[10px] text-amber-400 font-medium">
                  {qt.qualificationReason}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Champion Podium Box if Champion exists */}
      {championTeam && (
        <div className="bg-gradient-to-r from-amber-500 via-amber-400 to-yellow-500 text-slate-950 rounded-2xl p-6 shadow-2xl shadow-amber-500/20 text-center space-y-2 border-2 border-amber-300 animate-pulse">
          <div className="inline-flex p-3 bg-slate-950 rounded-2xl text-amber-400 mb-1 shadow-lg">
            <Trophy className="w-10 h-10" />
          </div>
          <div className="text-xs uppercase font-mono font-black tracking-widest text-slate-900">
            TURNUVA ŞAMPİYONU
          </div>
          <h1 className="text-3xl font-black tracking-tight drop-shadow-sm">
            🏆 {championTeam.name} 🏆
          </h1>
          <p className="text-xs font-semibold text-slate-900">
            Tebrikler! Bütün rakiplerini eleyerek kupanın sahibi oldu!
          </p>
        </div>
      )}

      {/* Tournament Bracket Flow Layout */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-center">

        {/* Left: Semi-Finals (5 cols) */}
        <div className="lg:col-span-6 space-y-6">
          <div className="text-xs font-bold text-slate-400 uppercase font-mono tracking-wider flex items-center space-x-2">
            <span className="w-2 h-2 rounded-full bg-emerald-500" />
            <span>Yarı Final Maçları</span>
          </div>

          <div className="space-y-6">
            {renderMatchCard(sf1)}
            {renderMatchCard(sf2)}
          </div>
        </div>

        {/* Right: Final & 3rd Place (6 cols) */}
        <div className="lg:col-span-6 space-y-6">
          <div className="text-xs font-bold text-amber-400 uppercase font-mono tracking-wider flex items-center space-x-2">
            <span className="w-2 h-2 rounded-full bg-amber-400" />
            <span>Final & Üçüncülük Maçı</span>
          </div>

          <div className="space-y-6">
            {renderMatchCard(finalMatch, true)}
            {renderMatchCard(thirdPlace)}
          </div>
        </div>

      </div>

    </div>
  );
};

src/components/GroupStandings.tsx:
import React from 'react';
import { GroupId, TeamStats } from '../types';
import { CheckCircle2, Award, XCircle, Info } from 'lucide-react';

interface GroupStandingsProps {
  standingsByGroup: Record<GroupId, TeamStats[]>;
  bestSecondTeamId?: string;
  onSelectGroup?: (groupId: GroupId) => void;
  selectedGroupFilter?: GroupId | 'ALL';
}

export const GroupStandings: React.FC<GroupStandingsProps> = ({
  standingsByGroup,
  bestSecondTeamId,
  selectedGroupFilter = 'ALL',
}) => {
  const groupsToShow: GroupId[] =
    selectedGroupFilter === 'ALL'
      ? ['A', 'B', 'C']
      : [selectedGroupFilter as GroupId];

  return (
    <div className="space-y-6">

      {/* Group Tables Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {groupsToShow.map((gid) => {
          const groupStandings = standingsByGroup[gid] || [];
          const groupTitle = gid === 'A' ? 'A Grubu' : gid === 'B' ? 'B Grubu' : 'C Grubu';

          const headerGradient =
            gid === 'A'
              ? 'from-blue-600/30 to-slate-900 border-blue-500/30'
              : gid === 'B'
              ? 'from-purple-600/30 to-slate-900 border-purple-500/30'
              : 'from-amber-600/30 to-slate-900 border-amber-500/30';

          return (
            <div
              key={gid}
              className="bg-slate-900 border border-slate-800 rounded-2xl overflow-hidden shadow-xl flex flex-col justify-between"
            >
              <div>
                {/* Group Table Header */}
                <div className={`bg-gradient-to-r ${headerGradient} p-4 border-b border-slate-800 flex items-center justify-between`}>
                  <div className="flex items-center space-x-2">
                    <span className="w-2.5 h-2.5 rounded-full bg-emerald-400 animate-pulse" />
                    <h3 className="font-bold text-white text-base tracking-wide">{groupTitle}</h3>
                  </div>
                  <span className="text-xs text-slate-400 font-mono">3 Takım • 6 Maç</span>
                </div>

                {/* Table */}
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-xs text-slate-300">
                    <thead className="bg-slate-950/80 text-[11px] uppercase font-mono text-slate-400 border-b border-slate-800">
                      <tr>
                        <th className="py-2.5 px-3 w-8 text-center">#</th>
                        <th className="py-2.5 px-3">Takım</th>
                        <th className="py-2.5 px-2 text-center" title="Oynanan">O</th>
                        <th className="py-2.5 px-2 text-center" title="Galibiyet">G</th>
                        <th className="py-2.5 px-2 text-center" title="Beraberlik">B</th>
                        <th className="py-2.5 px-2 text-center" title="Mağlubiyet">M</th>
                        <th className="py-2.5 px-2 text-center hidden sm:table-cell" title="Atılan Gol">AG</th>
                        <th className="py-2.5 px-2 text-center hidden sm:table-cell" title="Yenen Gol">YG</th>
                        <th className="py-2.5 px-2 text-center font-bold text-slate-200" title="Avaraj">AV</th>
                        <th className="py-2.5 px-3 text-center font-bold text-amber-400" title="Puan">P</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-800/60 font-medium">
                      {groupStandings.map((st) => {
                        const isFirst = st.rank === 1;
                        const isSecond = st.rank === 2;
                        const isBestSecond = isSecond && st.teamId === bestSecondTeamId;

                        let rowBg = 'hover:bg-slate-800/50';
                        if (isFirst) {
                          rowBg = 'bg-emerald-950/20 hover:bg-emerald-950/40 border-l-2 border-emerald-500';
                        } else if (isBestSecond) {
                          rowBg = 'bg-amber-950/20 hover:bg-amber-950/40 border-l-2 border-amber-500';
                        } else if (isSecond) {
                          rowBg = 'bg-slate-800/30 hover:bg-slate-800/60 border-l-2 border-slate-600';
                        }

                        return (
                          <tr key={st.teamId} className={`transition-colors ${rowBg}`}>
                            {/* Rank */}
                            <td className="py-3 px-3 text-center font-mono font-bold">
                              <span
                                className={`inline-flex items-center justify-center w-5 h-5 rounded-full text-[11px] ${
                                  isFirst
                                    ? 'bg-emerald-500 text-slate-950'
                                    : isBestSecond
                                    ? 'bg-amber-500 text-slate-950'
                                    : 'bg-slate-800 text-slate-400'
                                }`}
                              >
                                {st.rank}
                              </span>
                            </td>

                            {/* Team Name */}
                            <td className="py-3 px-3">
                              <div className="flex items-center space-x-2">
                                <span
                                  className="w-2.5 h-2.5 rounded-full shrink-0"
                                  style={{ backgroundColor: st.color || '#3b82f6' }}
                                />
                                <span className="font-semibold text-white truncate max-w-[110px] sm:max-w-[140px]">
                                  {st.teamName}
                                </span>
                              </div>
                            </td>

                            {/* Stats */}
                            <td className="py-3 px-2 text-center font-mono">{st.played}</td>
                            <td className="py-3 px-2 text-center font-mono text-emerald-400">{st.won}</td>
                            <td className="py-3 px-2 text-center font-mono text-slate-400">{st.drawn}</td>
                            <td className="py-3 px-2 text-center font-mono text-rose-400">{st.lost}</td>
                            <td className="py-3 px-2 text-center font-mono hidden sm:table-cell">{st.goalsFor}</td>
                            <td className="py-3 px-2 text-center font-mono hidden sm:table-cell">{st.goalsAgainst}</td>
                            <td
                              className={`py-3 px-2 text-center font-mono font-bold ${
                                st.goalDifference > 0
                                  ? 'text-emerald-400'
                                  : st.goalDifference < 0
                                  ? 'text-rose-400'
                                  : 'text-slate-400'
                              }`}
                            >
                              {st.goalDifference > 0 ? `+${st.goalDifference}` : st.goalDifference}
                            </td>
                            <td className="py-3 px-3 text-center font-mono font-bold text-sm text-amber-400">
                              {st.points}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>

              {/* Status Footer */}
              <div className="bg-slate-950/60 p-3 border-t border-slate-800 text-[11px] space-y-1">
                {groupStandings.map((st) => {
                  if (st.rank === 1) {
                    return (
                      <div key={st.teamId} className="flex items-center space-x-1.5 text-emerald-400">
                        <CheckCircle2 className="w-3.5 h-3.5 shrink-0" />
                        <span className="truncate">
                          <strong>{st.teamName}</strong> — Yarı Finalist (Lider)
                        </span>
                      </div>
                    );
                  }
                  if (st.rank === 2) {
                    const isBest = st.teamId === bestSecondTeamId;
                    return (
                      <div
                        key={st.teamId}
                        className={`flex items-center space-x-1.5 ${
                          isBest ? 'text-amber-400 font-medium' : 'text-slate-400'
                        }`}
                      >
                        <Award className="w-3.5 h-3.5 shrink-0" />
                        <span className="truncate">
                          <strong>{st.teamName}</strong> — {isBest ? 'En İyi 2. (Yarı Finalist)' : '2. Sıra (En İyi 2. Adayı)'}
                        </span>
                      </div>
                    );
                  }
                  return (
                    <div key={st.teamId} className="flex items-center space-x-1.5 text-slate-500">
                      <XCircle className="w-3.5 h-3.5 shrink-0" />
                      <span className="truncate">
                        <strong>{st.teamName}</strong> — Elendi
                      </span>
                    </div>
                  );
                })}
              </div>

            </div>
          );
        })}
      </div>

      {/* Legend Card */}
      <div className="bg-slate-900/80 border border-slate-800 rounded-xl p-4 flex flex-wrap items-center justify-between text-xs text-slate-400 gap-3">
        <div className="flex items-center space-x-1 text-slate-300 font-medium">
          <Info className="w-4 h-4 text-emerald-400" />
          <span>Puan Cetveli Açıklaması:</span>
        </div>
        <div className="flex flex-wrap items-center gap-4 text-[11px]">
          <span className="flex items-center space-x-1">
            <span className="w-2.5 h-2.5 rounded-full bg-emerald-500" />
            <span>1. Sıra (Yarı Final'e Çıkar)</span>
          </span>
          <span className="flex items-center space-x-1">
            <span className="w-2.5 h-2.5 rounded-full bg-amber-500" />
            <span>En İyi 2. Takım (Yarı Final'e Çıkar)</span>
          </span>
          <span className="font-mono text-slate-500">
            Kısaltmalar: O: Oynanan, G: Galibiyet, B: Beraberlik, M: Mağlubiyet, AG: Atılan Gol, YG: Yenen Gol, AV: Averaj, P: Puan
          </span>
        </div>
      </div>

    </div>
  );
};

src/components/Header.tsx:
import React from 'react';
import { Trophy, Users, Table, Award, RefreshCw, Zap, Sparkles, HardDrive } from 'lucide-react';

interface HeaderProps {
  activeTab: 'setup' | 'group' | 'bestSeconds' | 'knockout';
  setActiveTab: (tab: 'setup' | 'group' | 'bestSeconds' | 'knockout') => void;
  onLoadSample: () => void;
  onReset: () => void;
  onSimulateAll: () => void;
  onOpenSaveManager: () => void;
  playedMatchesCount: number;
  totalMatchesCount: number;
  championName?: string;
}

export const Header: React.FC<HeaderProps> = ({
  activeTab,
  setActiveTab,
  onLoadSample,
  onReset,
  onSimulateAll,
  onOpenSaveManager,
  playedMatchesCount,
  totalMatchesCount,
  championName,
}) => {
  const progressPercent = totalMatchesCount > 0 ? Math.round((playedMatchesCount / totalMatchesCount) * 100) : 0;

  return (
    <header className="bg-slate-900 border-b border-slate-800 text-white sticky top-0 z-40 shadow-xl">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between py-4 gap-4">

          {/* Brand & Title */}
          <div className="flex items-center space-x-3">
            <div className="w-12 h-12 rounded-xl bg-gradient-to-tr from-amber-500 via-emerald-500 to-cyan-500 p-0.5 shadow-lg shadow-emerald-900/30">
              <div className="w-full h-full bg-slate-900 rounded-[10px] flex items-center justify-center">
                <Trophy className="w-6 h-6 text-amber-400 animate-pulse" />
              </div>
            </div>
            <div>
              <div className="flex items-center space-x-2">
                <h1 className="text-xl font-bold tracking-tight bg-gradient-to-r from-white via-slate-100 to-emerald-400 bg-clip-text text-transparent">
                  Turnuva Puan Tablosu & Göstergesi
                </h1>
                <span className="text-xs bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 px-2 py-0.5 rounded-full font-mono font-medium">
                  3 Grup • 9 Takım
                </span>
              </div>
              <p className="text-xs text-slate-400">
                Grup Aşaması, Otomatik Rövanşlı Puan Cetveli ve En İyi 2. Eleme Sistemi
              </p>
            </div>
          </div>

          {/* Tournament Actions */}
          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={onOpenSaveManager}
              title="Kayıt durumu, yedek indir ve geri yükleme"
              className="px-3.5 py-1.5 bg-emerald-600/20 hover:bg-emerald-600/30 text-emerald-300 border border-emerald-500/40 rounded-lg text-xs font-semibold flex items-center space-x-2 shadow-md shadow-emerald-950/20 transition-all cursor-pointer"
            >
              <span className="relative flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
              </span>
              <HardDrive className="w-3.5 h-3.5 text-emerald-400" />
              <span>Kaydet & Devam Et</span>
            </button>

            <button
              onClick={onSimulateAll}
              title="Tüm maç sonuçlarını rastgele doldur"
              className="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-lg text-xs font-medium flex items-center space-x-1.5 transition-colors cursor-pointer"
            >
              <Zap className="w-3.5 h-3.5 text-amber-400" />
              <span>Rastgele Skorlar</span>
            </button>

            <button
              onClick={onLoadSample}
              className="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-slate-200 border border-slate-700 rounded-lg text-xs font-medium flex items-center space-x-1.5 transition-colors cursor-pointer"
            >
              <Sparkles className="w-3.5 h-3.5 text-emerald-400" />
              <span>Örnek Yükle</span>
            </button>

            <button
              onClick={onReset}
              className="px-3 py-1.5 bg-slate-800 hover:bg-rose-950/40 text-slate-400 hover:text-rose-300 border border-slate-700 hover:border-rose-800/50 rounded-lg text-xs font-medium flex items-center space-x-1.5 transition-colors cursor-pointer"
            >
              <RefreshCw className="w-3.5 h-3.5" />
              <span>Sıfırla</span>
            </button>
          </div>
        </div>

        {/* Progress Bar & Tabs */}
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between border-t border-slate-800/80 pt-2 pb-1 gap-2">

          {/* Navigation Tabs */}
          <nav className="flex items-center space-x-1 overflow-x-auto pb-1 sm:pb-0 scrollbar-none">
            <button
              onClick={() => setActiveTab('setup')}
              className={`px-3 py-2 rounded-lg text-xs sm:text-sm font-medium flex items-center space-x-2 transition-all whitespace-nowrap cursor-pointer ${
                activeTab === 'setup'
                  ? 'bg-emerald-500 text-slate-950 font-semibold shadow-md'
                  : 'text-slate-400 hover:text-white hover:bg-slate-800'
              }`}
            >
              <Users className="w-4 h-4" />
              <span>1. Takımlar ve Gruplar</span>
            </button>

            <button
              onClick={() => setActiveTab('group')}
              className={`px-3 py-2 rounded-lg text-xs sm:text-sm font-medium flex items-center space-x-2 transition-all whitespace-nowrap cursor-pointer ${
                activeTab === 'group'
                  ? 'bg-emerald-500 text-slate-950 font-semibold shadow-md'
                  : 'text-slate-400 hover:text-white hover:bg-slate-800'
              }`}
            >
              <Table className="w-4 h-4" />
              <span>2. Grup Maçları & Puan Durumu</span>
            </button>

            <button
              onClick={() => setActiveTab('bestSeconds')}
              className={`px-3 py-2 rounded-lg text-xs sm:text-sm font-medium flex items-center space-x-2 transition-all whitespace-nowrap cursor-pointer ${
                activeTab === 'bestSeconds'
                  ? 'bg-emerald-500 text-slate-950 font-semibold shadow-md'
                  : 'text-slate-400 hover:text-white hover:bg-slate-800'
              }`}
            >
              <Award className="w-4 h-4 text-amber-300" />
              <span>3. En İyi 2. Takım</span>
            </button>

            <button
              onClick={() => setActiveTab('knockout')}
              className={`px-3 py-2 rounded-lg text-xs sm:text-sm font-medium flex items-center space-x-2 transition-all whitespace-nowrap cursor-pointer ${
                activeTab === 'knockout'
                  ? 'bg-amber-500 text-slate-950 font-semibold shadow-md'
                  : 'text-slate-400 hover:text-white hover:bg-slate-800'
              }`}
            >
              <Trophy className="w-4 h-4" />
              <span>4. Eleme Aşaması</span>
              {championName && (
                <span className="ml-1 bg-amber-900/80 text-amber-200 text-[10px] px-1.5 py-0.5 rounded-full border border-amber-400/40 font-bold">
                  🏆 {championName}
                </span>
              )}
            </button>
          </nav>

          {/* Match Completion Stats */}
          <div className="flex items-center space-x-3 text-xs text-slate-400 bg-slate-950/60 px-3 py-1.5 rounded-lg border border-slate-800/80 self-start sm:self-auto">
            <span>Oynanan Maçlar:</span>
            <span className="font-mono text-emerald-400 font-bold">
              {playedMatchesCount} / {totalMatchesCount}
            </span>
            <div className="w-16 bg-slate-800 rounded-full h-1.5 overflow-hidden">
              <div
                className="bg-emerald-500 h-1.5 rounded-full transition-all duration-500"
                style={{ width: `${progressPercent}%` }}
              />
            </div>
            <span className="font-mono text-[11px] text-slate-300">{progressPercent}%</span>
          </div>

        </div>
      </div>
    </header>
  );
};

src/components/MatchList.tsx:
import React, { useState } from 'react';
import { GroupId, Match, Team } from '../types';
import { Filter, Zap, RotateCcw, CheckCircle2, Clock } from 'lucide-react';

interface MatchListProps {
  matches: Match[];
  teams: Team[];
  onScoreChange: (matchId: string, homeScore: number | null, awayScore: number | null) => void;
  onSimulateUnplayed: () => void;
  onResetAllScores: () => void;
}

export const MatchList: React.FC<MatchListProps> = ({
  matches,
  teams,
  onScoreChange,
  onSimulateUnplayed,
  onResetAllScores,
}) => {
  const [selectedGroup, setSelectedGroup] = useState<GroupId | 'ALL'>('ALL');
  const [selectedRound, setSelectedRound] = useState<number | 'ALL'>('ALL');
  const [statusFilter, setStatusFilter] = useState<'ALL' | 'PLAYED' | 'UNPLAYED'>('ALL');

  const getTeam = (teamId: string) => teams.find((t) => t.id === teamId);

  // Filter matches
  const filteredMatches = matches.filter((m) => {
    if (selectedGroup !== 'ALL' && m.groupId !== selectedGroup) return false;
    if (selectedRound !== 'ALL' && m.round !== selectedRound) return false;
    if (statusFilter === 'PLAYED' && !m.isPlayed) return false;
    if (statusFilter === 'UNPLAYED' && m.isPlayed) return false;
    return true;
  });

  return (
    <div className="space-y-6">

      {/* Control Bar & Filters */}
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-4 shadow-lg flex flex-col md:flex-row md:items-center justify-between gap-4">

        {/* Filters Group */}
        <div className="flex flex-wrap items-center gap-3">
          <div className="flex items-center space-x-2 text-xs text-slate-400 font-semibold uppercase tracking-wider">
            <Filter className="w-3.5 h-3.5 text-emerald-400" />
            <span>Filtrele:</span>
          </div>

          {/* Group Filter */}
          <select
            value={selectedGroup}
            onChange={(e) => setSelectedGroup(e.target.value as GroupId | 'ALL')}
            className="bg-slate-950 text-white text-xs font-medium border border-slate-800 rounded-xl px-3 py-2 focus:outline-none focus:border-emerald-500 cursor-pointer"
          >
            <option value="ALL">Tüm Gruplar (A, B, C)</option>
            <option value="A">Grup A Maçları</option>
            <option value="B">Grup B Maçları</option>
            <option value="C">Grup C Maçları</option>
          </select>

          {/* Round Filter */}
          <select
            value={selectedRound === 'ALL' ? 'ALL' : selectedRound.toString()}
            onChange={(e) =>
              setSelectedRound(e.target.value === 'ALL' ? 'ALL' : parseInt(e.target.value, 10))
            }
            className="bg-slate-950 text-white text-xs font-medium border border-slate-800 rounded-xl px-3 py-2 focus:outline-none focus:border-emerald-500 cursor-pointer"
          >
            <option value="ALL">Tüm Haftalar (1 - 6)</option>
            <option value="1">1. Hafta (İlk Maç)</option>
            <option value="2">2. Hafta (İlk Maç)</option>
            <option value="3">3. Hafta (İlk Maç)</option>
            <option value="4">4. Hafta (Rövanş)</option>
            <option value="5">5. Hafta (Rövanş)</option>
            <option value="6">6. Hafta (Rövanş)</option>
          </select>

          {/* Status Filter */}
          <div className="flex items-center bg-slate-950 p-1 rounded-xl border border-slate-800">
            <button
              onClick={() => setStatusFilter('ALL')}
              className={`px-2.5 py-1 rounded-lg text-xs font-medium cursor-pointer ${
                statusFilter === 'ALL' ? 'bg-slate-800 text-white font-bold' : 'text-slate-400 hover:text-white'
              }`}
            >
              Tümü
            </button>
            <button
              onClick={() => setStatusFilter('PLAYED')}
              className={`px-2.5 py-1 rounded-lg text-xs font-medium cursor-pointer ${
                statusFilter === 'PLAYED' ? 'bg-emerald-600 text-white font-bold' : 'text-slate-400 hover:text-white'
              }`}
            >
              Oynanmış
            </button>
            <button
              onClick={() => setStatusFilter('UNPLAYED')}
              className={`px-2.5 py-1 rounded-lg text-xs font-medium cursor-pointer ${
                statusFilter === 'UNPLAYED' ? 'bg-amber-600 text-white font-bold' : 'text-slate-400 hover:text-white'
              }`}
            >
              Bekleyen
            </button>
          </div>
        </div>

        {/* Quick Actions */}
        <div className="flex items-center space-x-2">
          <button
            onClick={onSimulateUnplayed}
            className="px-3 py-2 bg-emerald-600/20 hover:bg-emerald-600 text-emerald-300 hover:text-white border border-emerald-500/40 rounded-xl text-xs font-semibold flex items-center space-x-1.5 transition-all cursor-pointer"
          >
            <Zap className="w-3.5 h-3.5 text-amber-400" />
            <span>Skorları Otomatik Doldur</span>
          </button>

          <button
            onClick={onResetAllScores}
            className="px-3 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-xl text-xs font-medium flex items-center space-x-1.5 transition-colors cursor-pointer"
          >
            <RotateCcw className="w-3.5 h-3.5" />
            <span>Skorları Temizle</span>
          </button>
        </div>

      </div>

      {/* Match Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredMatches.length === 0 ? (
          <div className="col-span-full py-12 text-center text-slate-500 bg-slate-900/50 border border-slate-800 rounded-2xl">
            Seçilen filtrelere uygun maç bulunamadı.
          </div>
        ) : (
          filteredMatches.map((match) => {
            const homeTeam = getTeam(match.homeTeamId);
            const awayTeam = getTeam(match.awayTeamId);

            const isLeg2 = match.round >= 4;

            return (
              <div
                key={match.id}
                className={`bg-slate-900 border rounded-2xl p-4 shadow-lg flex flex-col justify-between space-y-3 transition-all hover:border-slate-700 ${
                  match.isPlayed
                    ? 'border-emerald-500/30 bg-slate-900/90'
                    : 'border-slate-800'
                }`}
              >
                {/* Header info */}
                <div className="flex items-center justify-between text-xs text-slate-400 border-b border-slate-800/80 pb-2">
                  <div className="flex items-center space-x-2">
                    <span className="font-bold text-slate-200 bg-slate-800 px-2 py-0.5 rounded font-mono">
                      Grup {match.groupId}
                    </span>
                    <span className="text-[11px] text-slate-400">
                      {match.round}. Hafta {isLeg2 ? '(Rövanş)' : '(İlk Maç)'}
                    </span>
                  </div>

                  {match.isPlayed ? (
                    <span className="flex items-center space-x-1 text-emerald-400 text-[11px] font-semibold bg-emerald-500/10 px-2 py-0.5 rounded-full border border-emerald-500/20">
                      <CheckCircle2 className="w-3 h-3" />
                      <span>Tamamlandı</span>
                    </span>
                  ) : (
                    <span className="flex items-center space-x-1 text-amber-400 text-[11px] font-medium bg-amber-500/10 px-2 py-0.5 rounded-full border border-amber-500/20">
                      <Clock className="w-3 h-3" />
                      <span>Bekliyor</span>
                    </span>
                  )}
                </div>

                {/* Score Editor Section */}
                <div className="flex items-center justify-between py-2">

                  {/* Home Team */}
                  <div className="flex-1 flex flex-col items-center text-center space-y-1.5 pr-2">
                    <div
                      className="w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs text-white shadow-md"
                      style={{ backgroundColor: homeTeam?.color || '#3b82f6' }}
                    >
                      {homeTeam?.shortName || 'EV'}
                    </div>
                    <span className="font-semibold text-xs text-white line-clamp-1 max-w-[100px]">
                      {homeTeam?.name || 'Ev Sahibi'}
                    </span>
                  </div>

                  {/* Score Inputs */}
                  <div className="flex items-center space-x-2 shrink-0">
                    <input
                      type="number"
                      min={0}
                      max={20}
                      value={match.homeScore !== null ? match.homeScore : ''}
                      onChange={(e) => {
                        const val = e.target.value === '' ? null : parseInt(e.target.value, 10);
                        onScoreChange(
                          match.id,
                          isNaN(val as number) ? null : val,
                          match.awayScore
                        );
                      }}
                      placeholder="-"
                      className="w-11 h-11 bg-slate-950 text-emerald-400 font-mono font-black text-lg text-center rounded-xl border border-slate-700 focus:outline-none focus:border-emerald-500 shadow-inner"
                    />

                    <span className="text-slate-600 font-bold text-lg">:</span>

                    <input
                      type="number"
                      min={0}
                      max={20}
                      value={match.awayScore !== null ? match.awayScore : ''}
                      onChange={(e) => {
                        const val = e.target.value === '' ? null : parseInt(e.target.value, 10);
                        onScoreChange(
                          match.id,
                          match.homeScore,
                          isNaN(val as number) ? null : val
                        );
                      }}
                      placeholder="-"
                      className="w-11 h-11 bg-slate-950 text-emerald-400 font-mono font-black text-lg text-center rounded-xl border border-slate-700 focus:outline-none focus:border-emerald-500 shadow-inner"
                    />
                  </div>

                  {/* Away Team */}
                  <div className="flex-1 flex flex-col items-center text-center space-y-1.5 pl-2">
                    <div
                      className="w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs text-white shadow-md"
                      style={{ backgroundColor: awayTeam?.color || '#3b82f6' }}
                    >
                      {awayTeam?.shortName || 'DEP'}
                    </div>
                    <span className="font-semibold text-xs text-white line-clamp-1 max-w-[100px]">
                      {awayTeam?.name || 'Deplasman'}
                    </span>
                  </div>

                </div>

                {/* Footer Clear / Quick fill */}
                <div className="flex items-center justify-between text-[11px] text-slate-500 pt-1 border-t border-slate-800/60">
                  <span>Maç #{match.matchNumber}</span>
                  {match.isPlayed && (
                    <button
                      onClick={() => onScoreChange(match.id, null, null)}
                      className="text-slate-400 hover:text-rose-400 transition-colors cursor-pointer"
                    >
                      Skoru Sıfırla
                    </button>
                  )}
                </div>

              </div>
            );
          })
        )}
      </div>

    </div>
  );
};

